/* Generated by quickwins/build.py from content/*.csv. BSB text from bereanbible.com (public domain), verified against biblehub.com/bsb. */
window.TB_DAYS=[{"theme": "Faith", "teen": {"ref": "Hebrews 11:1", "text": "Now faith is the assurance of what we hope for and the certainty of what we do not see."}, "adult": {"ref": "Colossians 3:23", "text": "Whatever you do, work at it with your whole being, as for the Lord and not for men,", "note": "Monday meetings, spreadsheets, school runs: none of it is small when it's offered to God."}, "night": {"ref": "Matthew 11:28", "text": "Come to Me, all you who are weary and burdened, and I will give you rest.", "note": "You carried a lot today. You don't have to carry it into tonight."}, "story": "Noah hammering beams under a dry, cloudless sky while neighbors laugh and jeer from the ridge. Pip deadpans, 'So... no forecast, no water, just vibes?' Lumi answers with the verse, and then the first raindrop hits the deck: a slow-motion, goosebumps beat.", "prayer": "God, help me build today on what You promised, even before I can see it. Amen."}, {"theme": "Courage", "teen": {"ref": "Joshua 1:9", "text": "Have I not commanded you to be strong and courageous? Do not be afraid; do not be discouraged, for the LORD your God is with you wherever you go."}, "adult": {"ref": "Isaiah 41:10", "text": "Do not fear, for I am with you; do not be afraid, for I am your God. I will strengthen you; I will surely help you; I will uphold you with My righteous right hand.", "note": "Before the inbox, the news and the to-do list, hear this: He is with you and He will hold you up."}, "night": {"ref": "1 Peter 5:7", "text": "Cast all your anxiety on Him, because He cares for you.", "note": "Name the worries out loud, one by one, and hand each one over before you sleep."}, "story": "Benny tells the story in talking-head cuts, with animated flashbacks of the robotics showcase, the mic feedback and 600 faces staring at him. Pip pops into frame: 'Spoiler, he survived.' Lumi lands on the podium and speaks the verse, and in the flashback Benny breathes, restarts and nails it.", "prayer": "Lord, when I'm scared, remind me You walk in first. Amen."}, {"theme": "Kindness", "teen": {"ref": "Ephesians 4:32", "text": "Be kind and tenderhearted to one another, forgiving each other just as in Christ God forgave you."}, "adult": {"ref": "Proverbs 16:3", "text": "Commit your works to the LORD and your plans will be achieved.", "note": "Clarity often comes after commitment. Give Him the plan, then take the next step."}, "night": {"ref": "Psalm 4:8", "text": "I will lie down and sleep in peace, for You alone, O LORD, make me dwell in safety.", "note": "Locks and alarms help, but your real safety tonight is the Lord Himself."}, "story": "Shot from Gracie's POV in the cafeteria, the two choices appear as game-style prompts: [Keep scrolling] or [Sit down]. Pip, from her backpack: 'If you pick scrolling, I'm telling Grandpa.' She sits down. Lumi speaks the verse over a slow-motion moment of the new kid smiling for the first time all week.", "prayer": "Jesus, make me the kind one in the room today, especially when it costs me something. Amen."}, {"theme": "Gratitude", "teen": {"ref": "1 Thessalonians 5:18", "text": "Give thanks in every circumstance, for this is God’s will for you in Christ Jesus."}, "adult": {"ref": "Ecclesiastes 4:9-10", "text": "Two are better than one, because they have a good return for their labor. For if one falls down, his companion can lift him up; but pity the one who falls without another to help him up!", "note": "Marriage isn't two people never falling. It's two people refusing to let the other stay down."}, "night": {"ref": "Ephesians 4:26", "text": "‘Be angry, yet do not sin.’ Do not let the sun set upon your anger,", "note": "Anger isn't the sin. Letting it settle in overnight is. Who do you need to make peace with before you sleep?"}, "story": "A fast, cozy-aesthetic montage cut to the beat: Grandpa Eli's burnt pancakes, Gracie's half-finished sketchbook, Benny's robot face-planting, Wren asleep mid-chirp, an autumn sunset. Each clip gets a handwritten caption ('Grandpa's terrible pancakes 10/10'). Lumi closes on the verse as the last shot holds on the family laughing.", "prayer": "Father, open my eyes to the small gifts I'd usually scroll past. Thank You. Amen."}, {"theme": "Forgiveness", "teen": {"ref": "Colossians 3:13", "text": "Bear with one another and forgive any complaint you may have against someone else. Forgive as the Lord forgave you."}, "adult": {"ref": "2 Timothy 1:7", "text": "For God has not given us a spirit of fear, but of power, love, and self-control.", "note": "Fear is a feeling, not a calling. You've been given power, love and self-control for today."}, "night": {"ref": "Philippians 4:6-7", "text": "Be anxious for nothing, but in everything, by prayer and petition, with thanksgiving, present your requests to God. And the peace of God, which surpasses all understanding, will guard your hearts and your minds in Christ Jesus.", "note": "Trade the worry for a thank-you and a request."}, "story": "Joseph, now ruler of Egypt, stands over the brothers who sold him as they kneel, terrified and starving. The score drops out; Pip whispers, 'Okay, this is the revenge arc, right?' Instead Joseph breaks down weeping and embraces them, and Lumi speaks the verse.", "prayer": "God, I don't want to carry this grudge any more. Help me let it go the way You let mine go. Amen."}, {"theme": "Hope", "teen": {"ref": "Jeremiah 29:11", "text": "For I know the plans I have for you, declares the LORD, plans to prosper you and not to harm you, to give you a future and a hope."}, "adult": {"ref": "Psalm 90:17", "text": "May the favor of the Lord our God rest upon us; establish for us the work of our hands—yes, establish the work of our hands!", "note": "Ask God to make what you build today last longer than the deadline."}, "night": {"ref": "Psalm 46:10", "text": "‘Be still and know that I am God; I will be exalted among the nations, I will be exalted over the earth.’", "note": "Five quiet minutes, no screens. Stillness is where knowing happens."}, "story": "Gracie's phone screen fills the frame as she texts Benny that she didn't make the art academy. Typing dots appear and disappear. Pip reads over her shoulder: 'He's typing a novel.' Benny's reply is a screenshot of the verse, with Lumi's glow pulsing across the screen as she reads it aloud.", "prayer": "Lord, when my plans fall apart, hold my future steady. Amen."}, {"theme": "Peace", "teen": {"ref": "John 14:27", "text": "Peace I leave with you; My peace I give to you. I do not give to you as the world gives. Do not let your hearts be troubled; do not be afraid."}, "adult": {"ref": "Micah 6:8", "text": "He has shown you, O man, what is good. And what does the LORD require of you but to act justly, to love mercy, and to walk humbly with your God?", "note": "Do justly, love mercy, walk humbly: a whole job description in one verse."}, "night": {"ref": "Matthew 5:4", "text": "Blessed are those who mourn, for they will be comforted.", "note": "If you're grieving this season, your tears are not a lack of faith. Comfort is promised."}, "story": "The Sea of Galilee at night, the boat pitching, waves exploding over the deck and the disciples bailing in panic. Pip, soaked and clinging to the mast: 'Is NOBODY going to wake Him up?!' Jesus rises and the storm goes still in a single breath. Lumi speaks the verse in the eerie, perfect calm.", "prayer": "Jesus, speak peace over the storm in my head tonight. Amen."}, {"theme": "Friendship", "teen": {"ref": "Proverbs 17:17", "text": "A friend loves at all times, and a brother is born for adversity."}, "adult": {"ref": "Proverbs 27:17", "text": "As iron sharpens iron, so one man sharpens another.", "note": "Adult friendships take intention. Text the friend who makes you better."}, "night": {"ref": "Psalm 147:3", "text": "He heals the brokenhearted and binds up their wounds.", "note": "Some wounds don't show. God sees them all, and He's gentle with them."}, "story": "Gracie sees the Instagram story: her whole friend group at the fall festival, no invite. Pip, flatly: 'Cool cool cool. Love that for them.' Then Wren shows up at the door with two hot ciders, and Benny is right behind him. Lumi speaks the verse as the three of them have the better night.", "prayer": "God, make me a friend who shows up, and send me friends who do the same. Amen."}, {"theme": "Strength", "teen": {"ref": "Philippians 4:13", "text": "I can do all things through Christ who gives me strength."}, "adult": {"ref": "Isaiah 43:19", "text": "Behold, I am about to do something new; even now it is coming. Do you not see it? Indeed, I will make a way in the wilderness and streams in the desert.", "note": "A new job, a move, an empty nest: God specializes in roads through wilderness."}, "night": {"ref": "Isaiah 26:3", "text": "You will keep in perfect peace the steadfast of mind, because he trusts in You.", "note": "Where your mind rests tonight matters. Set it on Him."}, "story": "A dim Roman prison, chains clinking, as Paul writes by a sliver of light. Pip squints: 'Wait. He wrote the gym verse... here?' Lumi explains that Paul meant strength for any situation, full or hungry, free or chained, and speaks the verse as the light falls across the page.", "prayer": "Christ, be my strength where I've run out of my own. Amen."}, {"theme": "Trust", "teen": {"ref": "Proverbs 3:5-6", "text": "Trust in the LORD with all your heart, and lean not on your own understanding; in all your ways acknowledge Him, and He will make your paths straight."}, "adult": {"ref": "Philippians 1:6", "text": "being confident of this, that He who began a good work in you will carry it on to completion until the day of Christ Jesus.", "note": "You're not a finished project, and God isn't a quitter."}, "night": {"ref": "Matthew 6:34", "text": "Therefore do not worry about tomorrow, for tomorrow will worry about itself. Today has enough trouble of its own.", "note": "Tomorrow's problems get tomorrow's grace. Tonight, rest."}, "story": "Rapid-fire cuts: Gracie with three color-coded planners, Benny re-checking his robot's code at 2 AM, Wren with 47 browser tabs open titled 'what if.' Lumi lands on the planner and speaks the verse. Final shot: Gracie closes one planner and actually goes to sleep.", "prayer": "Lord, I hand You my planner, my worries and my what-ifs. Lead the way. Amen."}, {"theme": "Anxiety / God's Care", "teen": {"ref": "Matthew 6:26", "text": "Look at the birds of the air: They do not sow or reap or gather into barns, and yet your heavenly Father feeds them. Are you not much more valuable than they?"}, "adult": {"ref": "Ephesians 2:10", "text": "For we are God’s workmanship, created in Christ Jesus to do good works, which God prepared in advance as our way of life.", "note": "You were designed on purpose, for purpose. Today has good works already waiting."}, "night": {"ref": "Psalm 30:5", "text": "For His anger is fleeting, but His favor lasts a lifetime. Weeping may stay the night, but joy comes in the morning.", "note": "If tonight is a weeping night, hold on. Morning is coming."}, "story": "Wren spirals in bed, and his thoughts appear as floating doomscroll notifications. Pip, half asleep: 'Bro. You're a bird. You don't even have a 401(k).' Lumi glows on and points out the window at the birds that are fed every single day, then speaks the verse.", "prayer": "Father, You feed the birds. Remind my anxious heart that You've got me too. Amen."}, {"theme": "Love", "teen": {"ref": "1 John 4:19", "text": "We love because He first loved us."}, "adult": {"ref": "Joshua 24:15b", "text": "As for me and my house, we will serve the LORD!", "note": "Whatever the culture chooses, you can set the direction for your home."}, "night": {"ref": "Revelation 21:4", "text": "‘He will wipe away every tear from their eyes,’ and there will be no more death or mourning or crying or pain, for the former things have passed away.", "note": "For everyone missing someone: this is not the end of the story."}, "story": "A ragged son trudges up a dusty road, rehearsing his apology. Far off, his father sees him and RUNS, robes flying, which was undignified for a man in that culture. Pip, quietly: 'He didn't even let him finish the speech.' Lumi speaks the verse over the embrace.", "prayer": "God, You loved me first. Help me love like that. Amen."}, {"theme": "Let Your Light Shine", "teen": {"ref": "Matthew 5:16", "text": "In the same way, let your light shine before men, that they may see your good deeds and glorify your Father in heaven."}, "adult": {"ref": "Proverbs 31:25", "text": "Strength and honor are her clothing, and she can laugh at the days to come.", "note": "Put on strength and dignity before you put on anything else today."}, "night": {"ref": "Psalm 62:1", "text": "In God alone my soul finds rest; my salvation comes from Him.", "note": "Waiting rooms, test results, unanswered emails: let your soul wait on Him instead."}, "story": "Lumi does a dramatic 'glow-up' transition, from one tiny flicker to blazing gold, and the light spreads as the family hands out cocoa and lanterns at a dark Halloween-night street. Each act of kindness lights another porch until the whole valley is glowing. Lumi speaks the verse over a drone-style wide shot.", "prayer": "Jesus, let my life point people to You, not to me. Amen."}, {"theme": "The Good Shepherd", "teen": {"ref": "Psalm 23:1", "text": "The LORD is my shepherd; I shall not want."}, "adult": {"ref": "James 1:2-3", "text": "Consider it pure joy, my brothers, when you encounter trials of many kinds, because you know that the testing of your faith develops perseverance.", "note": "The hard thing you're facing is building something in you that a comfortable life never could."}, "night": {"ref": "Psalm 127:2", "text": "In vain you rise early and stay up late, toiling for bread to eat—for He gives sleep to His beloved.", "note": "Burning the candle at both ends isn't faithfulness. Sleep is a gift from God, too."}, "story": "Young David alone on a moonlit hillside as a lion drags off a lamb. Pip gasps and covers his eyes. David charges, the action stays in silhouette, and he returns cradling the lamb. Pip, shaky: 'He'd do that... for one of us?' Lumi speaks the verse.", "prayer": "Good Shepherd, lead me today. I'll follow. Amen."}, {"theme": "Joy", "teen": {"ref": "Psalm 118:24", "text": "This is the day that the LORD has made; we will rejoice and be glad in it."}, "adult": {"ref": "Romans 12:2", "text": "Do not be conformed to this world, but be transformed by the renewing of your mind. Then you will be able to test and approve what is the good, pleasing, and perfect will of God.", "note": "Your feed shapes your mind. Fill it today with something that renews it."}, "night": {"ref": "Mark 6:31", "text": "And He said to them, ‘Come with Me privately to a solitary place, and let us rest for a while.’ For many people were coming and going, and they did not even have time to eat.", "note": "Even Jesus pulled His team away to rest. You're allowed to step back."}, "story": "Chaos captions stack up: Benny's alarm didn't go off, Grandpa Eli's pancakes are on fire, Wren lost his homework, and it's raining sideways. Pip dances anyway, ridiculously, in the kitchen. Lumi joins the dance and speaks the verse, and by the end the whole family is dancing.", "prayer": "Lord, even on a chaotic day, help me find a reason to be glad. Amen."}, {"theme": "Patience", "teen": {"ref": "Isaiah 40:31", "text": "But those who wait upon the LORD will renew their strength; they will mount up with wings like eagles; they will run and not grow weary, they will walk and not faint."}, "adult": {"ref": "1 Corinthians 15:58", "text": "Therefore, my beloved brothers, be steadfast and immovable. Always excel in the work of the Lord, because you know that your labor in the Lord is not in vain.", "note": "Unseen effort is not wasted effort. Not one hour given to Him is in vain."}, "night": {"ref": "1 Corinthians 13:7", "text": "It bears all things, believes all things, hopes all things, endures all things.", "note": "Love in marriage is less fireworks and more endurance. Thank God for the person who stays."}, "story": "David, anointed but hunted, shelters in a cave while soldiers' torches pass outside. Pip, frustrated: 'Why didn't God just fast-forward?' Lumi explains that the waiting was forming him, and speaks the verse as an eagle rises past the cave mouth into the dawn.", "prayer": "God, teach me to wait well and trust Your timing. Amen."}, {"theme": "Helping Others", "teen": {"ref": "Galatians 6:2", "text": "Carry one another’s burdens, and in this way you will fulfill the law of Christ."}, "adult": {"ref": "Psalm 37:5", "text": "Commit your way to the LORD; trust in Him, and He will do it.", "note": "Commit, trust, and let God handle the outcome."}, "night": {"ref": "Psalm 103:2", "text": "Bless the LORD, O my soul, and do not forget all His kind deeds—", "note": "Before bed, name three things He did today. Gratitude remembers."}, "story": "In talking-head cuts, Gracie explains that Benny stayed up every night that week tutoring her at the kitchen table with flashcards and terrible chemistry puns. Pip: 'The puns were the real burden.' Lumi speaks the verse as the flashback shows the B-minus taped to the fridge.", "prayer": "Jesus, show me whose load I can help carry today. Amen."}, {"theme": "Identity", "teen": {"ref": "Psalm 139:14", "text": "I praise You, for I am fearfully and wonderfully made. Marvelous are Your works, and I know this very well."}, "adult": {"ref": "Ephesians 4:2", "text": "with all humility and gentleness, with patience, bearing with one another in love,", "note": "Patience with your spouse today might be the most spiritual thing you do."}, "night": {"ref": "Psalm 55:22", "text": "Cast your burden upon the LORD and He will sustain you; He will never let the righteous be shaken.", "note": "Bills, diagnoses, deadlines: whatever weighs on you, He can carry it."}, "story": "Gracie scrolls perfect filtered faces, then catches her reflection in the dark phone screen. Pip leans in: 'Fun fact: that girl in the ad has three filters and a ring light.' Lumi glows on the mirror and speaks the verse, and the filters peel away from the feed one by one.", "prayer": "Creator, when I compare myself, remind me You made me on purpose. Amen."}, {"theme": "Overcoming Fear", "teen": {"ref": "Psalm 56:3", "text": "When I am afraid, I put my trust in You."}, "adult": {"ref": "Proverbs 22:6", "text": "Train up a child in the way he should go, and when he is old he will not depart from it.", "note": "Small, faithful moments with your kids add up to a lifetime."}, "night": {"ref": "2 Corinthians 4:16", "text": "Therefore we do not lose heart. Though our outer self is wasting away, yet our inner self is being renewed day by day.", "note": "Aging bodies, tired eyes: your inner self is still being renewed."}, "story": "David, recognized in Gath, the Philistine city, surrounded by guards, sweating as whispers spread. Pip: 'Oh, he's SO caught.' David writes on a scrap of parchment by firelight, and Lumi speaks the verse as he fakes madness, scratching at the gate and letting spit run down his beard, to slip away (1 Samuel 21).", "prayer": "Lord, when fear shows up, I'm choosing to trust You. Amen."}, {"theme": "Honesty", "teen": {"ref": "Proverbs 12:22", "text": "Lying lips are detestable to the LORD, but those who deal faithfully are His delight."}, "adult": {"ref": "Psalm 27:1", "text": "The LORD is my light and my salvation—whom shall I fear? The LORD is the stronghold of my life—whom shall I dread?", "note": "Name the fear. Then ask the question David asked: whom shall I fear?"}, "night": {"ref": "Romans 8:28", "text": "And we know that God works all things together for the good of those who love Him, who are called according to His purpose.", "note": "Not everything is good. But God works all things toward good."}, "story": "Benny's group-project partner slides over the leaked answer key, and the classroom freezes as game-style choices appear. Pip, side-eye: 'Nobody would know. Except, you know... God. And me. I'm right here.' Benny slides it back, and Lumi speaks the verse.", "prayer": "God, give me the courage to tell the truth, even when it's easier not to. Amen."}, {"theme": "Generosity", "teen": {"ref": "2 Corinthians 9:7", "text": "Each one should give what he has decided in his heart to give, not out of regret or compulsion. For God loves a cheerful giver."}, "adult": {"ref": "Hebrews 12:1", "text": "Therefore, since we are surrounded by such a great cloud of witnesses, let us throw off every encumbrance and the sin that so easily entangles, and let us run with endurance the race set out for us.", "note": "What weight can you put down today to run lighter?"}, "night": {"ref": "Psalm 91:1", "text": "He who dwells in the shelter of the Most High will abide in the shadow of the Almighty.", "note": "Tonight, dwell. Don't just visit God's presence. Stay there."}, "story": "A huge restless crowd on a hillside at sunset as the disciples panic over the cost. A boy steps forward holding five loaves and two fish. Pip: 'Respectfully, that's a snack.' Jesus gives thanks, the baskets keep filling, and Lumi speaks the verse.", "prayer": "Jesus, make me generous with what I have, even when it feels small. Amen."}, {"theme": "Prayer", "teen": {"ref": "Matthew 7:7", "text": "Ask, and it will be given to you; seek, and you will find; knock, and the door will be opened to you."}, "adult": {"ref": "Deuteronomy 8:18", "text": "But remember that it is the LORD your God who gives you the power to gain wealth, in order to confirm His covenant that He swore to your fathers even to this day.", "note": "Paycheck or pinch, your ability to provide comes from Him."}, "night": {"ref": "Romans 15:13", "text": "Now may the God of hope fill you with all joy and peace as you believe in Him, so that you may overflow with hope by the power of the Holy Spirit.", "note": "Hope isn't wishful thinking. It's a gift the Spirit pours in."}, "story": "Quick-cut list: Benny asking for help BEFORE the robot catches fire. Gracie texting 'can we talk?' instead of ghosting. Wren praying before spiraling, for once. Lumi caps it off by speaking the verse while knocking on a glowing door that swings open.", "prayer": "Father, I'm asking, seeking and knocking. Thank You for listening. Amen."}, {"theme": "Fresh Start", "teen": {"ref": "Lamentations 3:22-23", "text": "Because of the loving devotion of the LORD we are not consumed, for His mercies never fail. They are new every morning; great is Your faithfulness!"}, "adult": {"ref": "Galatians 5:22-23", "text": "But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. Against such things there is no law.", "note": "Which fruit is hardest for you today? Ask for that one."}, "night": {"ref": "Psalm 121:1-2", "text": "I lift up my eyes to the hills. From where does my help come? My help comes from the LORD, the Maker of heaven and earth.", "note": "Look up from the screen. Your help comes from the Maker of heaven and earth."}, "story": "Peter by a courtyard fire, denying Jesus three times, then the rooster crows and he runs off weeping. Days later, at dawn on a beach, the risen Jesus is cooking breakfast. Pip whispers, 'Is this... the morning after?' Lumi speaks the verse as Peter splashes toward the shore.", "prayer": "Lord, thank You that Your mercy is new this morning. I'm starting again with You. Amen."}, {"theme": "Humility", "teen": {"ref": "Philippians 2:3", "text": "Do nothing out of selfish ambition or empty pride, but in humility consider others more important than yourselves."}, "adult": {"ref": "Psalm 118:6", "text": "The LORD is on my side; I will not be afraid. What can man do to me?", "note": "Walk into the room today knowing whose side you're on."}, "night": {"ref": "Romans 8:38-39", "text": "For I am convinced that neither death nor life, neither angels nor principalities, neither the present nor the future, nor any powers, neither height nor depth, nor anything else in all creation, will be able to separate us from the love of God that is in Christ Jesus our Lord.", "note": "Nothing you did today, and nothing waiting tomorrow, can separate you from His love."}, "story": "Benny's team wins regionals, and he's mid-victory-lap in his own head (rendered as an epic slow-mo stadium fantasy). Pip pulls the plug on the fantasy: 'Your teammate Maya wrote half that code.' Benny hands Maya the mic, and Lumi speaks the verse.", "prayer": "God, keep me humble when I win and kind when others do. Amen."}, {"theme": "Small Beginnings", "teen": {"ref": "Zechariah 4:10a", "text": "For who has despised the day of small things?"}, "adult": {"ref": "Nehemiah 8:10b", "text": "Do not grieve, for the joy of the LORD is your strength.", "note": "Running on empty? Joy in God is fuel, not decoration."}, "night": {"ref": "Exodus 14:14", "text": "The LORD will fight for you; you need only to be still.", "note": "Some battles aren't yours to fight. Be still tonight."}, "story": "Gracie's day-in-the-life vlog: sketching in class, painting after homework, uploading to 3 views (one of them Grandpa Eli, who comments 'Very nice. -Grandpa'). Pip: 'Honestly, iconic comment.' Lumi speaks the verse, then a 'Day 100' card shows her art hanging at a local café.", "prayer": "Lord, bless my small beginnings and help me not to quit. Amen."}, {"theme": "Grief", "teen": {"ref": "Psalm 34:18", "text": "The LORD is near to the brokenhearted; He saves the contrite in spirit."}, "adult": {"ref": "Esther 4:14b", "text": "And who knows if perhaps you have come to the kingdom for such a time as this?", "note": "Your job, your neighborhood, your family: you're there on purpose."}, "night": {"ref": "Psalm 16:11", "text": "You have made known to me the path of life; You will fill me with joy in Your presence, with eternal pleasures at Your right hand.", "note": "Whatever path tomorrow brings, fullness of joy is found in His presence."}, "story": "Grandpa Eli sits in his woodshop holding Grandma's old reading glasses, his first fall without her. Benny comes in and sits beside him, saying nothing. Pip, for once, doesn't make a joke and leans against Grandpa's leg. Lumi's glow fills the room gently as she speaks the verse.", "prayer": "God, be close to every broken heart tonight, including mine. Amen."}, {"theme": "Wisdom", "teen": {"ref": "James 1:5", "text": "Now if any of you lacks wisdom, he should ask God, who gives generously to all without finding fault, and it will be given to him."}, "adult": {"ref": "Proverbs 4:23", "text": "Guard your heart with all diligence, for from it flow springs of life.", "note": "Guard what you watch, who you listen to and what you replay. It all flows from the heart."}, "night": {"ref": "Hebrews 13:5", "text": "Keep your lives free from the love of money and be content with what you have, for God has said: ‘Never will I leave you, never will I forsake you.’", "note": "Lonely or wanting more? Contentment grows from His promise: never alone."}, "story": "Young King Solomon, overwhelmed on a too-big throne, prays at night for wisdom instead of riches. Pip: 'Not even a little gold? Respect.' Smash-cut to Solomon's famous judgment between two mothers, with real stakes, and Lumi speaks the verse.", "prayer": "Father, I need wisdom. Thank You for giving it freely. Amen."}, {"theme": "Perseverance", "teen": {"ref": "Galatians 6:9", "text": "Let us not grow weary in well-doing, for in due time we will reap a harvest if we do not give up."}, "adult": {"ref": "Isaiah 40:29", "text": "He gives power to the faint and increases the strength of the weak.", "note": "Running on four hours of sleep and caffeine? He gives power to the faint."}, "night": {"ref": "Psalm 73:26", "text": "My flesh and my heart may fail, but God is the strength of my heart and my portion forever.", "note": "When your body or your heart gives out, God is still your portion."}, "story": "Nehemiah's builders work with a trowel in one hand and a sword at their side while enemies taunt from the ridge. Pip: 'This is the most stressful group project ever.' The last stone drops into place and Lumi speaks the verse.", "prayer": "Jesus, when I'm tired of doing right, give me strength to keep going. Amen."}, {"theme": "Peacemaking", "teen": {"ref": "Matthew 5:9", "text": "Blessed are the peacemakers, for they will be called sons of God."}, "adult": {"ref": "2 Corinthians 12:9", "text": "But He said to me, ‘My grace is sufficient for you, for My power is perfected in weakness.’ Therefore I will boast all the more gladly in my weaknesses, so that the power of Christ may rest on me.", "note": "Your weak spot might be exactly where His power shows up."}, "night": {"ref": "John 16:33", "text": "I have told you these things so that in Me you may have peace. In the world you will have tribulation. But take courage; I have overcome the world!", "note": "Trouble is promised. So is His victory."}, "story": "Animated comment bubbles fly like arrows between Wren and a rival bird over a dumb online argument. Pip, eating popcorn: 'Should I... help? Or keep watching?' Lumi speaks the verse, and Wren types and then deletes a nasty reply, sending 'fair point, my bad' instead.", "prayer": "God, make me a peacemaker online and off. Amen."}, {"theme": "Blessing", "teen": {"ref": "Numbers 6:24-26", "text": "‘May the LORD bless you and keep you; may the LORD cause His face to shine upon you and be gracious to you; may the LORD lift up His countenance toward you and give you peace.’"}, "adult": {"ref": "Psalm 100:4", "text": "Enter His gates with thanksgiving and His courts with praise; give thanks to Him and bless His name.", "note": "Thanksgiving season starts now. Begin today with thanks before requests."}, "night": {"ref": "Psalm 107:1", "text": "Give thanks to the LORD, for He is good; His loving devotion endures forever.", "note": "Thirty days, sixty verses. End tonight with thanks: He is good."}, "story": "The whole family gathers on the hill at sunset, and Lumi rises and speaks the ancient priestly blessing over them. Then her glow spirals into darkness, and a single voice-less beam of light splits the void. Card: 'GENESIS TO GLORY. 12.25.' Pip's eyes go wide: 'Oh, it's THAT story.'", "prayer": "Lord, bless us and keep us, and make Your face shine on us. Amen."}];
window.TB_MOODS=[{"id": "anxious", "label": "Anxious", "ref": "1 Peter 5:7", "text": "Cast all your anxiety on Him, because He cares for you.", "note": "Name the worry. Then hand it over. You were never meant to carry it alone."}, {"id": "thankful", "label": "Thankful", "ref": "Psalm 107:1", "text": "Give thanks to the LORD, for He is good; His loving devotion endures forever.", "note": "Gratitude grows when you say it out loud. Tell someone one good thing today."}, {"id": "tired", "label": "Tired", "ref": "Matthew 11:28", "text": "Come to Me, all you who are weary and burdened, and I will give you rest.", "note": "Rest isn't quitting. Jesus literally invites you to it."}, {"id": "brave", "label": "Brave", "ref": "Joshua 1:9", "text": "Have I not commanded you to be strong and courageous? Do not be afraid; do not be discouraged, for the LORD your God is with you wherever you go.", "note": "Whatever you're walking into, you're not walking in alone."}];
